INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7070372, 1075719, 10848, '<td valign="top">Very nice! Good use of the position of your lighting. Very effective shadow. You really emphasized the somber mood.</td>', 'Very nice! Good use of the position of your lighting. Very effective shadow. You really emphasized the somber mood.', '2013-07-15 01:05:39.000000', NULL, 1),
(7070383, 1075707, 96751, '<td valign="top">I especially like the fine blades of glass under the mushroom cap :-)</td>', 'I especially like the fine blades of glass under the mushroom cap :-)', '2013-07-15 01:15:46.000000', NULL, 1),
(7070393, 1075653, 10848, '<td valign="top">Love this one!</td>', 'Love this one!', '2013-07-15 01:42:13.000000', NULL, 1),
(7070413, 1075721, 103032, '<td valign="top">The shadows are distinctive. Strong light creating the shadows.<br/>The people are going in the same direction. <br/>The people and shadows have great leading lines to the vanishing point.<br/>Kind of eerie/creepy/cult-like that everyone/everything is headed into that light.<br/>Not that I pay much attention to titles, but the title works well too.<br/> <br/>This image encompasses what I imagined this challenge to be.<br/>My favorite. This should Blue. A 10.</td>', 'The shadows are distinctive. Strong light creating the shadows.The people are going in the same direction. The people and shadows have great leading lines to the vanishing point.Kind of eerie/creepy/cult-like that everyone/everything is headed into that light.Not that I pay much attention to titles, but the title works well too. This image encompasses what I imagined this challenge to be.My favorite. This should Blue. A 10.', '2013-07-15 02:28:58.000000', NULL, 1),
(7070469, 1075742, 28742, '<td valign="top">Well done! Bravo! Bye bye Miss <strike>American</strike> Polish Pie. :)</td>', 'Well done! Bravo! Bye bye Miss American Polish Pie. :)', '2013-07-15 04:31:03.000000', NULL, 1),
