(7070640, 1075697, 28427, '<td valign="top">I love the shadow falling over the angel''s face, but the bg is too distracting in colour and structure for my taste.</td>', 'I love the shadow falling over the angel''s face, but the bg is too distracting in colour and structure for my taste.', '2013-07-15 11:13:10.000000', NULL, 1),
(7070648, 1075694, 12611, '<td valign="top">Great jagged lines, and the eye shading is fantastic. Light and shadow fighting the eternal fight.</td>', 'Great jagged lines, and the eye shading is fantastic. Light and shadow fighting the eternal fight.', '2013-07-15 11:41:31.000000', NULL, 1),
(7070649, 1075220, 23484, '<td valign="top">Great shot. This should be in the fine art challenge.</td>', 'Great shot. This should be in the fine art challenge.', '2013-07-15 11:43:01.000000', NULL, 1),
(7070650, 1075659, 12611, '<td valign="top">A terrific shadow skyline cast on the buildings.</td>', 'A terrific shadow skyline cast on the buildings.', '2013-07-15 11:43:08.000000', NULL, 1),
(7070651, 1075467, 23484, '<td valign="top">Beautiful image. Love the starkness.</td>', 'Beautiful image. Love the starkness.', '2013-07-15 11:43:33.000000', NULL, 1),
