(7070654, 1075690, 23484, '<td valign="top">Nice catch and great composition.</td>', 'Nice catch and great composition.', '2013-07-15 11:44:34.000000', NULL, 1),
(7070655, 1075491, 23484, '<td valign="top">The grainy look is very nice.</td>', 'The grainy look is very nice.', '2013-07-15 11:45:52.000000', NULL, 1),
