(7070665, 1075741, 28427, '<td valign="top">You''re living the same situation as we do at our place :) Texting, texting, toilet, have drink, texting, eat, text,....  My kids would even text while they''re asleep if it would be possible.<br/>Taking in account that you''ve used only the light of the cellphone, than this is a very nice result.</td>', 'You''re living the same situation as we do at our place :) Texting, texting, toilet, have drink, texting, eat, text,....  My kids would even text while they''re asleep if it would be possible.Taking in account that you''ve used only the light of the cellphone, than this is a very nice result.', '2013-07-15 12:14:16.000000', NULL, 1),
(7070668, 1075438, 28427, '<td valign="top">Amazing light.</td>', 'Amazing light.', '2013-07-15 12:29:51.000000', NULL, 1),
