(7070690, 1075438, 118154, '<td valign="top">First image I looked at in this challenge and its a real nice one,hope to see this near the top.</td>', 'First image I looked at in this challenge and its a real nice one,hope to see this near the top.', '2013-07-15 13:09:26.000000', NULL, 1),
(7070691, 1075719, 118154, '<td valign="top">Top ten for sure,lovely.</td>', 'Top ten for sure,lovely.', '2013-07-15 13:11:12.000000', NULL, 1),
