(7075388, 1075438, 99263, '<td valign="top">Congratz on 2nd place. It''s a beautiful image in it''s own right but to me it does not meet the challenge requirement that light and shadow vie with each other for attention. At least not the way I envisioned it.</td>', 'Congratz on 2nd place. It''s a beautiful image in it''s own right but to me it does not meet the challenge requirement that light and shadow vie with each other for attention. At least not the way I envisioned it.', '2013-07-22 04:52:36.000000', NULL, 0),
(7075389, 1075683, 99263, '<td valign="top">Congratz on 3rd place. It''s an exceptionally beautiful image in it''s own right but to me it does not meet the challenge requirement that light and shadow vie with each other for attention. At least not the way I envisioned it.</td>', 'Congratz on 3rd place. It''s an exceptionally beautiful image in it''s own right but to me it does not meet the challenge requirement that light and shadow vie with each other for attention. At least not the way I envisioned it.', '2013-07-22 04:54:22.000000', NULL, 0),
