INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7075462, 1075683, 19825, '<td valign="top">Wonderfully whimsical. Excellent job.</td>', 'Wonderfully whimsical. Excellent job.', '2013-07-22 10:41:42.000000', NULL, 0),
(7075464, 1075702, 60581, '<td valign="top">This one was my favorite!</td>', 'This one was my favorite!', '2013-07-22 10:53:06.000000', NULL, 0),
(7075469, 1075683, 24454, '<td valign="top">Johanna!  This is so beautiful!  The finest of art!</td>', 'Johanna!  This is so beautiful!  The finest of art!', '2013-07-22 11:09:59.000000', NULL, 0),
(7075474, 1075735, 12611, '<td valign="top">Congrats on the first blue. A very fine shot.</td>', 'Congrats on the first blue. A very fine shot.', '2013-07-22 11:19:23.000000', NULL, 0),
(7075476, 1075735, 113411, '<td valign="top">Congratulations Nikki ....really well done!</td>', 'Congratulations Nikki ....really well done!', '2013-07-22 11:27:04.000000', NULL, 0),
(7075498, 1075438, 138630, '<td valign="top">The golden tones and rays of light take this out of the ordinary.  A beautiful image.  Congratulations on the ribbon.</td>', 'The golden tones and rays of light take this out of the ordinary.  A beautiful image.  Congratulations on the ribbon.', '2013-07-22 11:58:09.000000', NULL, 0),
(7075500, 1075683, 138630, '<td valign="top">This is just gorgeous, Johanna - my pick for the top.  I love the airy feel the gauzy skirt and caught in the air moment lend to it.  And the timeless look of the floor - both the wood and the tile - is a wonderfully chosen background.  Congratulations on the ribbon.</td>', 'This is just gorgeous, Johanna - my pick for the top.  I love the airy feel the gauzy skirt and caught in the air moment lend to it.  And the timeless look of the floor - both the wood and the tile - is a wonderfully chosen background.  Congratulations on the ribbon.', '2013-07-22 12:04:51.000000', NULL, 0),
(7075504, 1075702, 138630, '<td valign="top">Lovely!  The moire of the fabric really does give this a most wonderful textured look.  Congratulations on the HM.</td>', 'Lovely!  The moire of the fabric really does give this a most wonderful textured look.  Congratulations on the HM.', '2013-07-22 12:07:10.000000', NULL, 0),
(7075506, 1075719, 138630, '<td valign="top">Very very nice, Wendy.  I love the added interest that the banister uprights lend the shadow, and the tones are quite lovely.  This has a natural selective color look that is very effective and emphasizes the contrast between the girl and the shadow.  Congratulations on the HM.</td>', 'Very very nice, Wendy.  I love the added interest that the banister uprights lend the shadow, and the tones are quite lovely.  This has a natural selective color look that is very effective and emphasizes the contrast between the girl and the shadow.  Congratulations on the HM.', '2013-07-22 12:10:50.000000', NULL, 0),
(7075508, 1075721, 138630, '<td valign="top">Could be morning or evening, to me - sad that they already have worn down postures.  Says something about the daily grind, doesn''t it.  Wonderful long shadows that lead us to the figures.  Congratulations on the top ten.</td>', 'Could be morning or evening, to me - sad that they already have worn down postures.  Says something about the daily grind, doesn''t it.  Wonderful long shadows that lead us to the figures.  Congratulations on the top ten.', '2013-07-22 12:13:58.000000', NULL, 0),
(7075509, 1075735, 122678, '<td valign="top">Congratulations BEAUTIFUL... image.</td>', 'Congratulations BEAUTIFUL... image.', '2013-07-22 12:15:08.000000', NULL, 0),
(7075512, 1075571, 138630, '<td valign="top">I''m with <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=114285" rel="nofollow" target="_blank">Neat</a> - really want to know the story.  The guy especially appears to be in a theatrical performance - otherwise his garb is unusual to say the least.  I think it''s particularly lovely the way the light picks up the woman''s head.  Nice!  Congratulations on the top ten.</td>', 'I''m with  Neat - really want to know the story.  The guy especially appears to be in a theatrical performance - otherwise his garb is unusual to say the least.  I think it''s particularly lovely the way the light picks up the woman''s head.  Nice!  Congratulations on the top ten.', '2013-07-22 12:16:54.000000', NULL, 0),
(7075513, 1075435, 138630, '<td valign="top">The light is very well handled here, Margaret - beautiful result.  Congratulations on the top ten.</td>', 'The light is very well handled here, Margaret - beautiful result.  Congratulations on the top ten.', '2013-07-22 12:17:39.000000', NULL, 0),
(7075514, 1075732, 138630, '<td valign="top">Great tones, textures, and lines.  Congratulations on the top ten.</td>', 'Great tones, textures, and lines.  Congratulations on the top ten.', '2013-07-22 12:18:29.000000', NULL, 0),
(7075515, 1075610, 138630, '<td valign="top">Simple but very high interest - I think the balance between the busy, highly textured, lit background and the strong, simple shadow is excellent.  Congratulations on the top ten.</td>', 'Simple but very high interest - I think the balance between the busy, highly textured, lit background and the strong, simple shadow is excellent.  Congratulations on the top ten.', '2013-07-22 12:20:13.000000', NULL, 0),
(7075516, 1075704, 138630, '<td valign="top">High interest and impact.  Should have scored higher but a nice finish anyway.</td>', 'High interest and impact.  Should have scored higher but a nice finish anyway.', '2013-07-22 12:22:00.000000', NULL, 0),
(7075517, 1075683, 94815, '<td valign="top">You have projected yourself in this image. Nice finish.</td>', 'You have projected yourself in this image. Nice finish.', '2013-07-22 12:22:04.000000', NULL, 0),
(7075518, 1075702, 122678, '<td valign="top">Congratulations!<br/>I thought this image might be yours, it has your name all over it.  Your work is amazing!</td>', 'Congratulations!I thought this image might be yours, it has your name all over it.  Your work is amazing!', '2013-07-22 12:23:21.000000', NULL, 0),
(7075520, 1075743, 138630, '<td valign="top">Love the way the light is hitting him in the midst of the dark area and that he is perfectly placed.  Great lines.  Nicely seen.</td>', 'Love the way the light is hitting him in the midst of the dark area and that he is perfectly placed.  Great lines.  Nicely seen.', '2013-07-22 12:24:25.000000', NULL, 0),
